mapper.select:
SELECT db.* FROM document_block db JOIN source_document sd ON sd.id = db.source_document_id
WHERE sd.tenant_id = #{tenantId}
  AND db.source_document_id = #{fileDocumentId}
  AND db.status = 'active'
  AND db.id IN
  #{blockId}
ORDER BY db.block_order ASC, db.id ASC
LIMIT #{limit}

SELECT db.* FROM document_block db JOIN source_document sd ON sd.id = db.source_document_id
WHERE sd.tenant_id = #{tenantId}
  AND db.source_document_id = #{fileDocumentId}
  AND db.status = 'active'
  AND db.block_order BETWEEN #{startOrder} AND #{endOrder}
ORDER BY db.block_order ASC, db.id ASC
LIMIT #{limit}

SELECT db.* FROM document_block db JOIN source_document sd ON sd.id = db.source_document_id
WHERE sd.tenant_id = #{tenantId}
  AND db.source_document_id = #{fileDocumentId}
  AND db.external_block_id IN
  #{externalBlockId}
ORDER BY db.block_order ASC, db.id ASC
LIMIT #{limit}

mapper.update:
UPDATE document_block db JOIN source_document sd ON sd.id = db.source_document_id
SET db.status = 'inactive'
WHERE sd.tenant_id = #{tenantId}
  AND db.source_document_id = #{fileDocumentId}
  AND db.status = 'active'

mapper.select:
SELECT db.* FROM document_block db JOIN source_document sd ON sd.id = db.source_document_id
WHERE sd.tenant_id = #{tenantId}
  AND db.source_document_id = #{fileDocumentId}
  AND db.status = 'active'
  AND db.block_order > #{afterBlockOrder}
ORDER BY db.block_order ASC, db.id ASC
LIMIT #{limit}

SELECT db.* FROM document_block db JOIN source_document file_doc ON file_doc.id = db.source_document_id WHERE file_doc.tenant_id = #{tenantId} AND file_doc.source_type = 'feishu' AND file_doc.sync_status <> 'archived' AND file_doc.parse_status IN ('parsed', 'completed') AND file_doc.embedding_status IN ('ready', 'completed') AND JSON_UNQUOTE(JSON_EXTRACT(file_doc.metadata_json, '$.documentKind')) = 'FILE' AND JSON_UNQUOTE(JSON_EXTRACT(file_doc.metadata_json, '$.indexStatus')) IN ('ready', 'completed') AND db.status = 'active' AND EXISTS ( SELECT 1 FROM source_document root_doc WHERE root_doc.tenant_id = #{tenantId} AND root_doc.id = CAST(JSON_UNQUOTE(JSON_EXTRACT(file_doc.metadata_json, '$.rootDocumentId')) AS UNSIGNED) AND root_doc.sync_status <> 'archived' )
AND (file_doc.created_by = #{viewerSubjectId} OR file_doc.permission_scope IN ('TEACHER_SHARED', 'TENANT_PUBLIC', 'PUBLIC_TEXTBOOK', 'MATH_VIP', 'CLASS_AUTHORIZED'))
AND file_doc.permission_scope IN ('TENANT_PUBLIC', 'PUBLIC_TEXTBOOK', 'MATH_VIP', 'CLASS_AUTHORIZED')
AND 1 = 0
AND file_doc.id IN #{documentId}
AND file_doc.permission_scope IN #{permissionScope}
AND db.id > #{afterBlockId} ORDER BY db.id ASC LIMIT #{limit}

SELECT db.* FROM document_block db JOIN source_document file_doc ON file_doc.id = db.source_document_id WHERE file_doc.tenant_id = #{tenantId} AND file_doc.source_type = 'feishu' AND file_doc.sync_status <> 'archived' AND file_doc.parse_status IN ('parsed', 'completed') AND file_doc.embedding_status IN ('ready', 'completed') AND JSON_UNQUOTE(JSON_EXTRACT(file_doc.metadata_json, '$.documentKind')) = 'FILE' AND JSON_UNQUOTE(JSON_EXTRACT(file_doc.metadata_json, '$.indexStatus')) IN ('ready', 'completed') AND db.status = 'active' AND db.id IN #{blockId} AND EXISTS ( SELECT 1 FROM source_document root_doc WHERE root_doc.tenant_id = #{tenantId} AND root_doc.id = CAST(JSON_UNQUOTE(JSON_EXTRACT(file_doc.metadata_json, '$.rootDocumentId')) AS UNSIGNED) AND root_doc.sync_status <> 'archived' )
AND (file_doc.created_by = #{viewerSubjectId} OR file_doc.permission_scope IN ('TEACHER_SHARED', 'TENANT_PUBLIC', 'PUBLIC_TEXTBOOK', 'MATH_VIP', 'CLASS_AUTHORIZED'))
AND file_doc.permission_scope IN ('TENANT_PUBLIC', 'PUBLIC_TEXTBOOK', 'MATH_VIP', 'CLASS_AUTHORIZED')
AND 1 = 0
AND file_doc.id IN #{documentId}
AND file_doc.permission_scope IN #{permissionScope}
LIMIT #{limit}
